# orders.rb - set-oriented rules over one table's dataset
ORDERS = DB[:orders]

def overdue_orders(as_of) = ORDERS.where { due < as_of }.select(:id, :due, :total)

def total_of(rows) = rows.sum { |row| row[:total] }

def flag_overdue(as_of) = ORDERS.where { due < as_of }.update(flagged: true)  # set-oriented write
